import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.DfDAiEgj.js";const o="/2bPM/img/sense_vs_cognition_AI.png",f=JSON.parse('{"title":"认知智能","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/cognition_AI.md","filePath":"ai-dive/cognition_AI.md","lastUpdated":null}'),r={name:"ai-dive/cognition_AI.md"};function _(l,t,s,c,p,d){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="认知智能" tabindex="-1">认知智能 <a class="header-anchor" href="#认知智能" aria-label="Permalink to &quot;认知智能&quot;">​</a></h1><p>2020年，是人工智能领域的扎实落地之年，也是从感知智能迈向认知智能的规模突破之年。知识图谱技术与图计算应用场景取得爆发性增长，从增强自然语言能力、人工智能模型可解释性、机器学习能力提升三个维度助力各大企业机构向认知智能领域演变。<a href="https://www.weiyangx.com/378231.html" target="_blank" rel="noreferrer">1</a></p><p>如果说感知智能时代，人工智能三要素是数据，算法，算力。</p><p>那么在认知智能时代，三要素则需要进一步迭代与提升，具体来说就是：</p><ul><li>算法不是关键，工程架构才是关键；</li><li>算力不是关键，人机协作才是关键；</li><li>数据(量)不是关键，数据的结构才是关键；</li></ul><p><img src="'+o+'" alt="感知智能VS认知智能"></p>',6)])])}const g=e(r,[["render",_]]);export{f as __pageData,g as default};
